import{_ as i,c as a,o as e,ag as t}from"./chunks/framework.B-aGGnuW.js";const c=JSON.parse('{"title":"Encryption","description":"","frontmatter":{},"headers":[],"relativePath":"encryption/index.md","filePath":"encryption/index.md","lastUpdated":1792149212000}'),n={name:"encryption/index.md"};function p(h,s,l,r,o,d){return e(),a("div",null,[...s[0]||(s[0]=[t(`<h1 id="encryption" tabindex="-1">Encryption <a class="header-anchor" href="#encryption" aria-label="Permalink to &quot;Encryption&quot;">​</a></h1><p>This alternative installs ext4 and optional swap inside LVM on LUKS2, with a separate unencrypted ESP at <code>/boot</code>. It covers UEFI with either GRUB or systemd-boot. Start here after <a href="/installation/live-setup">live setup</a>.</p><p>The root filesystem and swap are encrypted; the bootloader, kernel and initramfs on the ESP are not. This does not protect the boot files against tampering. <a href="https://wiki.archlinux.org/title/Unified_Extensible_Firmware_Interface/Secure_Boot" target="_blank" rel="noreferrer">Secure Boot</a> and <a href="https://wiki.archlinux.org/title/Unified_kernel_image" target="_blank" rel="noreferrer">unified kernel images</a> require additional setup.</p><h2 id="partition-the-disk" tabindex="-1">Partition the disk <a class="header-anchor" href="#partition-the-disk" aria-label="Permalink to &quot;Partition the disk&quot;">​</a></h2><p>Check the target carefully. The following operations destroy data on the partitions you format. Replace the NVMe examples with your actual devices.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">lsblk</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -o</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> NAME,SIZE,TYPE,FSTYPE,MOUNTPOINTS,MODEL</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cfdisk</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /dev/nvme0n1</span></span></code></pre></div><p>Use GPT and create:</p><table tabindex="0"><thead><tr><th>Partition</th><th>Size</th><th>Type</th><th>Purpose</th></tr></thead><tbody><tr><td><code>/dev/nvme0n1p1</code></td><td>1 GiB</td><td>EFI System (<code>ef00</code> in gdisk)</td><td><code>/boot</code></td></tr><tr><td><code>/dev/nvme0n1p2</code></td><td>Remaining space</td><td>Linux LUKS (<code>8309</code> in gdisk)</td><td>Encrypted container</td></tr></tbody></table><p>Preserve an existing ESP when dual booting. Do not format it; check that it has room for kernels and initramfs images.</p><h2 id="create-the-encrypted-container" tabindex="-1">Create the encrypted container <a class="header-anchor" href="#create-the-encrypted-container" aria-label="Permalink to &quot;Create the encrypted container&quot;">​</a></h2><p>Use the intended console keyboard layout when entering the passphrase:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cryptsetup</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> luksFormat</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --type</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> luks2</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /dev/nvme0n1p2</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cryptsetup</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> open</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /dev/nvme0n1p2</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> cryptroot</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pvcreate</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /dev/mapper/cryptroot</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">vgcreate</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> main</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /dev/mapper/cryptroot</span></span></code></pre></div><p>The following optional swap volume is 4 GiB. Change its size for your workload, or skip it if using zram. Hibernation needs sufficiently large disk swap and separate <a href="https://wiki.archlinux.org/title/Power_management/Suspend_and_hibernate#Hibernation" target="_blank" rel="noreferrer">resume configuration</a>.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">lvcreate</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -L</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 4G</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -n</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> swap</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> main</span></span></code></pre></div><p>Create root using most of the remaining space, leaving room in the volume group for maintenance such as ext4&#39;s <code>e2scrub</code>:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">lvcreate</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -l</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 95%FREE</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -n</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> root</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> main</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">mkfs.ext4</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -L</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ROOT</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /dev/mapper/main-root</span></span></code></pre></div><p>If you created the swap volume:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">mkswap</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /dev/mapper/main-swap</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">swapon</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /dev/mapper/main-swap</span></span></code></pre></div><p>Format the ESP <strong>only if it is new</strong>:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">mkfs.fat</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -F32</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -n</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> EFI</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /dev/nvme0n1p1</span></span></code></pre></div><p>Mount root and the ESP:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">mount</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /dev/mapper/main-root</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /mnt</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">mount</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --mkdir</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /dev/nvme0n1p1</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /mnt/boot</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">findmnt</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -R</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /mnt</span></span></code></pre></div><p>Continue with <a href="/installation/base-installation">base installation</a>, adding <code>lvm2</code> to <code>pacstrap</code>. Follow the sidebar through system configuration, users, desktop and useful packages. The bootloader page returns to the next section before generating the initramfs.</p><h2 id="configure-the-initramfs" tabindex="-1">Configure the initramfs <a class="header-anchor" href="#configure-the-initramfs" aria-label="Permalink to &quot;Configure the initramfs&quot;">​</a></h2><p>Run this section inside the installed system&#39;s chroot, after setting <code>/etc/vconsole.conf</code>. Ensure the tools are installed:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pacman</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -S</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --needed</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> lvm2</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> cryptsetup</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">nano</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /etc/mkinitcpio.conf</span></span></code></pre></div><p>Use this systemd-based hook sequence:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">HOOKS</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">base</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> systemd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> autodetect</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> microcode</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> modconf</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> kms</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> keyboard</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> sd-vconsole</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> block</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> sd-encrypt</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> lvm2</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> filesystems</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> fsck</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span></code></pre></div><p><code>sd-vconsole</code> supplies the console keymap, <code>sd-encrypt</code> unlocks LUKS, and <code>lvm2</code> activates the root volume. Do not mix this sequence with the BusyBox <code>encrypt</code>/<code>keymap</code> hooks.</p><p>Find the UUID of the <strong>outer LUKS partition</strong>, not the filesystem or logical volume:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cryptsetup</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> luksUUID</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /dev/nvme0n1p2</span></span></code></pre></div><p>Return to <a href="/installation/install-bootloader">bootloader installation</a> and use this UUID in its encrypted-root instructions. That page generates the initramfs for all installed kernels.</p><h2 id="header-backup-and-ssd-discard" tabindex="-1">Header backup and SSD discard <a class="header-anchor" href="#header-backup-and-ssd-discard" aria-label="Permalink to &quot;Header backup and SSD discard&quot;">​</a></h2><p>Back up the LUKS header to separate, protected storage. Replace the output path with a mounted external backup location:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cryptsetup</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> luksHeaderBackup</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /dev/nvme0n1p2</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --header-backup-file</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /path/on/external/storage/arch-luks-header.img</span></span></code></pre></div><p>Keep this backup private: an old header and its old passphrase can still decrypt the data even after you change the current passphrase. See <a href="https://wiki.archlinux.org/title/Dm-crypt/Device_encryption#Backup_and_restore" target="_blank" rel="noreferrer">LUKS header backup</a>.</p><p>Enabling <code>fstrim.timer</code> alone does not pass discard through LUKS. Allowing discard is optional and reveals allocation patterns; review <a href="https://wiki.archlinux.org/title/Dm-crypt/Specialties#Discard/TRIM_support_for_solid_state_drives_(SSD)" target="_blank" rel="noreferrer">dm-crypt SSD support</a> before changing it.</p><p>Reference: <a href="https://wiki.archlinux.org/title/Dm-crypt/Encrypting_an_entire_system#LVM_on_LUKS" target="_blank" rel="noreferrer">LVM on LUKS</a>.</p>`,38)])])}const F=i(n,[["render",p]]);export{c as __pageData,F as default};
